package id.softchime;

import net.minecraft.client.gui.GuiGraphicsExtractor;

/** Banner image (supplied by the user) stored as a colour-rectangle table; drawn with plain fills. Generated. */
public final class Banner {
	public static final int W = 96, H = 55;
	private static final String PAL = "fdf767fdf428f9ea46f6cb4df5ae22f5a80af39f09e2d571dcb44de1a02eb7a95f519ed1d08733a38449498bd06f84773490ed2a8ff42181ebad663d7660367a362034566f220f09";
	private static final String DATA = ""; // per rect: palette index, x, width, y, height (hex bytes)
	private static int[] pal;
	private static int[] rects;

	private static void init() {
		if (pal != null) return;
		int[] p = new int[PAL.length() / 6];
		for (int i = 0; i < p.length; i++) p[i] = 0xFF000000 | Integer.parseInt(PAL.substring(i * 6, i * 6 + 6), 16);
		int[] r = new int[DATA.length() / 2];
		for (int i = 0; i < r.length; i++) r[i] = Integer.parseInt(DATA.substring(i * 2, i * 2 + 2), 16);
		rects = r; pal = p;
	}

	/** Draw scaled to the given width; returns the drawn height. */
	public static int draw(GuiGraphicsExtractor g, int x, int y, int width) {
		init();
		float s = width / (float) W;
		for (int k = 0; k < rects.length; k += 5) {
			int x1 = x + Math.round(rects[k + 1] * s), x2 = x + Math.round((rects[k + 1] + rects[k + 2]) * s);
			int y1 = y + Math.round(rects[k + 3] * s), y2 = y + Math.round((rects[k + 3] + rects[k + 4]) * s);
			if (x2 > x1 && y2 > y1) g.fill(x1, y1, x2, y2, pal[rects[k]]);
		}
		return Math.round(H * s);
	}
}
